void ensure_config(void) {
    const char *xdg = getenv("XDG_CONFIG_HOME");
    const char *home = getenv("HOME");
    char path[1024];
    char dir[1024];
    if (xdg && xdg[0]) {
        snprintf(path, sizeof(path), "%s/htop/htoprc", xdg);
        snprintf(dir, sizeof(dir), "%s/htop", xdg);
    } else if (home && home[0]) {
        snprintf(path, sizeof(path), "%s/.config/htop/htoprc", home);
        snprintf(dir, sizeof(dir), "%s/.config/htop", home);
    } else {
        return;
    }
    struct stat st;
    if (stat(path, &st) == 0) return; // exists
    // Create dirs
    // mkdir -p
    char tmp[1024];
    snprintf(tmp, sizeof(tmp), "%s", dir);
    // Create parent dirs
    for (char *p = tmp+1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            mkdir(tmp, 0755);
            *p = '/';
        }
    }
    mkdir(tmp, 0755);
    // Also need parent .config? Already handled by loop
    // Write file
    FILE *f = fopen(path, "w");
    if (f) {
        fputs(default_htoprc, f);
        fclose(f);
        chmod(path, 0600);
    }
}

