    if (!f) return;
    char line[256];
    long mem_total=0, mem_free=0, mem_avail=0, buffers=0, cached=0, swap_total=0, swap_free=0;
    while (fgets(line, sizeof(line), f)) {
        if (sscanf(line, "MemTotal: %ld", &mem_total)==1) g_mem_total_kb = mem_total;
        else if (sscanf(line, "MemAvailable: %ld", &mem_avail)==1) g_mem_available_kb = mem_avail;
        else if (sscanf(line, "SwapTotal: %ld", &swap_total)==1) g_swap_total_kb = swap_total;
        else if (sscanf(line, "SwapFree: %ld", &swap_free)==1) g_swap_free_kb = swap_free;
    }
    fclose(f);
}

