void format_mem(long kb, char *out, size_t outsz) {
    double mb = kb / 1024.0;
    double gb = mb / 1024.0;
    double tb = gb / 1024.0;
    if (tb >= 1.0) {
        // Use T
        if (tb < 10) snprintf(out, outsz, "%.2fT", tb);
        else if (tb < 100) snprintf(out, outsz, "%.1fT", tb);
        else snprintf(out, outsz, "%.0fT", tb);
    } else if (gb >= 1.0) {
        if (gb < 10) snprintf(out, outsz, "%.2fG", gb);
        else if (gb < 100) snprintf(out, outsz, "%.1fG", gb);
        else snprintf(out, outsz, "%.0fG", gb);
    } else {
        // M
        if (mb < 10) snprintf(out, outsz, "%.2fM", mb);
        else if (mb < 100) snprintf(out, outsz, "%.1fM", mb);
        else snprintf(out, outsz, "%.0fM", mb);
    }
}

void format_uptime(double secs, char *out, size_t outsz) {
    long s = (long)secs;
    long days = s / 86400;
    long rem = s % 86400;
    long h = rem / 3600;
    long m = (rem % 3600) / 60;
    long sec = rem % 60;
    if (days > 0) {
        snprintf(out, outsz, "%ld days, %02ld:%02ld:%02ld", days, h, m, sec);
    } else {
        snprintf(out, outsz, "%02ld:%02ld:%02ld", h, m, sec);
    }
}

