void read_processes(void) {
    DIR *d = opendir("/proc");
    if (!d) return;
    struct dirent *ent;
    g_nprocs = 0;
    while ((ent = readdir(d)) != NULL) {
        // Check if numeric
        char *end;
        long pid = strtol(ent->d_name, &end, 10);
        if (*end != '\0' || end == ent->d_name) continue;
        if (pid <= 0) continue;
        // Ensure capacity
        if (g_nprocs >= g_nprocs_alloc) {
            g_nprocs_alloc = g_nprocs_alloc ? g_nprocs_alloc*2 : 256;
            g_procs = realloc(g_procs, g_nprocs_alloc * sizeof(Proc));
        }
        Proc *p = &g_procs[g_nprocs];
        memset(p, 0, sizeof(Proc));
        p->pid = (int)pid;

        // Read stat
        char path[256];
        snprintf(path, sizeof(path), "/proc/%ld/stat", pid);
        FILE *f = fopen(path, "r");
        if (!f) continue;
        char stat_buf[4096];
        if (!fgets(stat_buf, sizeof(stat_buf), f)) { fclose(f); continue; }
        fclose(f);
        // Parse stat: pid (comm) state ppid pgrp session tty_nr tpgid flags minflt cminflt majflt cmajflt utime stime cutime cstime priority nice num_threads itrealvalue starttime vsize rss ...
        // comm may contain spaces and parentheses, need to find last ')'
        char *lparen = strchr(stat_buf, '(');
        char *rparen = strrchr(stat_buf, ')');
        if (!lparen || !rparen) continue;
        size_t comm_len = rparen - lparen - 1;
        if (comm_len >= sizeof(p->comm)) comm_len = sizeof(p->comm)-1;
        strncpy(p->comm, lparen+1, comm_len);
        p->comm[comm_len] = '\0';
        // After rparen+2, parse rest
        char *rest = rparen + 2;
        // state ppid pgrp session tty_nr tpgid flags minflt cminflt majflt cmajflt utime stime cutime cstime priority nice num_threads ...
        // We need: state, ppid, pgrp, session, tty_nr, tpgid, minflt, cminflt, majflt, cmajflt, utime, stime, cutime, cstime, priority, nice, num_threads, starttime, vsize, rss, ...
        // Use sscanf for first part
        char state;
        int ppid, pgrp, session, tty_nr, tpgid;
        unsigned long flags, minflt, cminflt, majflt, cmajflt, utime, stime;
        long cutime, cstime, priority, nice, num_threads;
        unsigned long long starttime;
        unsigned long vsize;
        long rss;
        // Note: flags is unsigned long, but we ignore
        int n = sscanf(rest, "%c %d %d %d %d %d %lu %lu %lu %lu %lu %lu %lu %ld %ld %ld %ld %ld %*d %llu %lu %ld",
            &state, &ppid, &pgrp, &session, &tty_nr, &tpgid, &flags, &minflt, &cminflt, &majflt, &cmajflt, &utime, &stime, &cutime, &cstime, &priority, &nice, &num_threads, &starttime, &vsize, &rss);
        if (n < 21) continue;
        p->state = state;
        p->ppid = ppid;
        p->pgrp = pgrp;
        p->session = session;
        p->tty_nr = tty_nr;
        p->tpgid = tpgid;
        p->minflt = minflt; p->cminflt=cminflt; p->majflt=majflt; p->cmajflt=cmajflt;
        p->utime=utime; p->stime=stime; p->cutime=cutime; p->cstime=cstime;
        p->priority=priority; p->nice=nice; p->num_threads=num_threads;
        p->starttime=starttime;
        p->vsize=vsize; p->rss=rss;
        p->total_time = utime + stime;
        // Processor? Need to parse further: after rss, there are many fields, processor is 39th field? Let's parse processor from stat: field 39 is processor.
        // Our sscanf stopped at rss (field 24). Need to get processor (field 39). Parse remaining.
        // Simpler: read /proc/[pid]/stat and count fields? Or read processor from /proc/[pid]/stat's 39th field.
        // Let's try to parse processor by counting.
        // After rss, fields are: rsslim, startcode, endcode, startstack, kstkesp, kstkeip, signal, blocked, sigignore, sigcatch, wchan, nswap, cnswap, exit_signal, processor, ...
        // We can sscanf the rest after rss? Easier: tokenize rest by spaces and get 39th field (0-indexed?).
        // rest contains fields from state (field 3) onwards. Field numbers: 1=pid,2=comm,3=state,4=ppid,... So rest[0] is state (field3). Processor is field39, so index in rest is 39-3=36 (0-based).
        {
            // Copy rest to temp and tokenize
            char tmp[4096];
            strncpy(tmp, rest, sizeof(tmp)-1);
            tmp[sizeof(tmp)-1]='\0';
            char *save=NULL;
            char *tok = strtok_r(tmp, " ", &save);
            int idx=0; // 0=state
            int proc = 0;
            while (tok) {
                if (idx==36) { proc = atoi(tok); break; }
                idx++;
                tok = strtok_r(NULL, " ", &save);
            }
            p->processor = proc;
        }
        // UID from /proc/[pid]/status? Or stat file owner?
