        }
        struct passwd *pw = getpwuid(p->uid);
        if (pw) {
            strncpy(p->user, pw->pw_name, sizeof(p->user)-1);
        } else {
            snprintf(p->user, sizeof(p->user), "%d", (int)p->uid);
        }
        // TTY? From tty_nr? Simplify: "?" 
        // tty_nr is device number: major = (tty_nr >> 8) & 0xff? Actually dev_t encoding? For simplicity, show "?" if 0 else "?".
        // Original shows "?" for most? In our captures, TTY column not displayed (Main screen doesn't show TTY). So ignore.
        snprintf(p->tty, sizeof(p->tty), "?");
        // cmdline
        snprintf(path, sizeof(path), "/proc/%ld/cmdline", pid);
        FILE *cf = fopen(path, "r");
        if (cf) {
            size_t len = fread(p->cmdline, 1, sizeof(p->cmdline)-1, cf);
            fclose(cf);
            p->cmdline[len]='\0';
            // Replace \0 with space, trim trailing spaces
            for (size_t i=0;i<len;i++) if (p->cmdline[i]=='\0') p->cmdline[i]=' ';
            // Trim trailing spaces
            while (len>0 && p->cmdline[len-1]==' ') { p->cmdline[len-1]='\0'; len--; }
            if (len==0) {
                // Use comm
                strncpy(p->cmdline, p->comm, sizeof(p->cmdline)-1);
            }
        } else {
            strncpy(p->cmdline, p->comm, sizeof(p->cmdline)-1);
        }
        // share? From /proc/[pid]/statm? statm: size resident shared text lib data dt
        snprintf(path, sizeof(path), "/proc/%ld/statm", pid);
        FILE *sf = fopen(path, "r");
        if (sf) {
            unsigned long size, resident, shared;
            if (fscanf(sf, "%lu %lu %lu", &size, &resident, &shared)==3) {
                p->share = shared;
            }
            fclose(sf);
        }
        // mem percent
        if (g_mem_total_kb > 0) {
            // rss is pages, convert to KB: pages * page_size /1024
            long rss_kb = p->rss * g_page_size / 1024;
            p->mem_percent = (double)rss_kb * 100.0 / g_mem_total_kb;
        } else {
            p->mem_percent = 0;
        }
        p->cpu_percent = 0.0; // first frame always 0

        // Apply filters early? We'll filter after reading all, but for now, check pid/user/filter
        // To match original Tasks count (system-wide, not filtered), we need to keep all for Tasks, but display filtered.
        // So don't skip here, just store. Filtering done later for display.
        g_nprocs++;
    }
    closedir(d);
}

