    int desc = get_sort_direction(key);
    // Handle string columns
    if (strcmp(key,"USER")==0 || strcmp(key,"Command")==0 || strcmp(key,"TTY")==0 || strcmp(key,"COMM")==0) {
        const char *sa=NULL, *sb=NULL;
        if (strcmp(key,"USER")==0) { sa=pa->user; sb=pb->user; }
        else if (strcmp(key,"Command")==0) { sa=pa->cmdline; sb=pb->cmdline; }
        else if (strcmp(key,"TTY")==0) { sa=pa->tty; sb=pb->tty; }
        else if (strcmp(key,"COMM")==0) { sa=pa->comm; sb=pb->comm; }
        int cmp = strcmp(sa, sb);
        if (cmp!=0) return desc ? -cmp : cmp;
        // Tie-breaker: PID ascending?
        return pa->pid - pb->pid;
    }
    if (strcmp(key,"STATE")==0) {
        int cmp = (int)pa->state - (int)pb->state;
        if (cmp!=0) return desc ? -cmp : cmp;
        return pa->pid - pb->pid;
    }
    const char *dummy;
    long long va = proc_get_sort_value(pa, key, &dummy);
    long long vb = proc_get_sort_value(pb, key, &dummy);
    if (va < vb) return desc ? 1 : -1;
    if (va > vb) return desc ? -1 : 1;
    // Tie: PID ascending (or for tree? Tree sorts children? For list view, tie-breaker PID?)
    return pa->pid - pb->pid;
}

