        else if (sscanf(line, "Shmem: %ld", &v)==1) g_mem_shmem_kb = v;
        else if (sscanf(line, "SwapTotal: %ld", &v)==1) g_swap_total_kb = v;
        else if (sscanf(line, "SwapFree: %ld", &v)==1) g_swap_free_kb = v;
    }
    fclose(f);
}"""

content=content.replace(old_read_meminfo, new_read_meminfo)

# Fix mem_used calculation in draw_meters
old_mem_calc = """    char mem_used_str[32], mem_total_str[32], swap_used_str[32], swap_total_str[32];
    long mem_used_kb = g_mem_total_kb - g_mem_available_kb;
    if (mem_used_kb < 0) mem_used_kb = 0;"""

new_mem_calc = """    char mem_used_str[32], mem_total_str[32], swap_used_str[32], swap_total_str[32];
    long mem_used_kb = g_mem_total_kb - g_mem_free_kb - g_mem_cached_kb - g_mem_buffers_kb - g_mem_sreclaim_kb + g_mem_shmem_kb;
    if (mem_used_kb < 0) mem_used_kb = 0;"""

content=content.replace(old_mem_calc, new_mem_calc)

# Fix RES to use statm resident instead of stat rss
# In read_processes, we set p->rss from stat, then later read statm for share. Change to use statm resident for rss.
# Find: p->vsize=vsize; p->rss=rss;
old_rss = """        p->vsize=vsize; p->rss=rss;"""
new_rss = """        p->vsize=vsize; p->rss=rss; // will be overwritten by statm resident below for accuracy"""

content=content.replace(old_rss, new_rss)

# After reading statm, overwrite rss
old_statm = """        snprintf(path, sizeof(path), "/proc/%ld/statm", pid);
        FILE *sf = fopen(path, "r");
        if (sf) {
            unsigned long size, resident, shared;
            if (fscanf(sf, "%lu %lu %lu", &size, &resident, &shared)==3) {
                p->share = shared;
            }
            fclose(sf);
        }"""

new_statm = """        snprintf(path, sizeof(path), "/proc/%ld/statm", pid);
        FILE *sf = fopen(path, "r");
        if (sf) {
            unsigned long size, resident, shared;
            if (fscanf(sf, "%lu %lu %lu", &size, &resident, &shared)==3) {
                p->share = shared;
                p->rss = (long)resident; // use statm resident for RES (matches htop)
            }
            fclose(sf);
        }"""

content=content.replace(old_statm, new_statm)

with open("tui.c","w") as f:
    f.write(content)
