void draw_search_footer(const char *query) {
    int maxy, maxx;
    getmaxyx(stdscr, maxy, maxx);
    move(maxy-1, 0);
    clrtoeol();
    printw("F3Next  S-F3Prev   EscCancel    Search: %s", query);
    refresh();
}

void draw_filter_footer(const char *query) {
    int maxy, maxx;
    getmaxyx(stdscr, maxy, maxx);
    move(maxy-1, 0);
    clrtoeol();
    printw("EnterDone  EscClear    Filter: %s", query);
    refresh();
}

// Find next matching process index at or after start (wrap), case-insensitive substring
int find_search_match(const char *query, int start, int direction) {
    if (!query || !*query) return -1;
    int n = g_ndisplay;
    if (n==0) return -1;
    if (direction >= 0) {
        for (int i=0;i<n;i++) {
            int idx = (start + i) % n;
            if (contains_case_insensitive(g_display_procs[idx].cmdline, query)) return idx;
        }
    } else {
        for (int i=0;i<n;i++) {
            int idx = (start - i + n*1000) % n;
            if (contains_case_insensitive(g_display_procs[idx].cmdline, query)) return idx;
        }
    }
    return -1;
}

void do_search(int *selected) {
    char query[256] = "";
    int qlen=0;
    int orig_selected = *selected;
    // Show footer
    timeout(-1); // blocking
    draw_search_footer(query);
    // Need to redraw main screen? Keep main screen, just footer changes. Already drawn.
    while (1) {
        int ch = getch();
        if (ch == 27) { // ESC
            *selected = orig_selected;
            break;
        } else if (ch == '\n' || ch == '\r' || ch == KEY_ENTER) {
            break;
        } else if (ch == KEY_F(3)) {
            // Next
            if (qlen>0) {
                int nxt = find_search_match(query, *selected+1, 1);
                if (nxt>=0) *selected = nxt;
                // Redraw processes? Need to redraw main screen with new selection, but keep search footer.
                // For simplicity, redraw entire screen (meters, header, processes) but with search footer (not normal footer).
                // We'll just redraw processes area manually? Easier: call draw functions but with custom footer.
                // To avoid complexity, just update selection and redraw processes + search footer.
                // Find start_row: need to know layout. Recompute as in main loop.
                // Simplify: return to main loop with updated selection? But search mode should stay active (allow further F3).
                // We'll redraw processes here.
                int maxy, maxx;
                getmaxyx(stdscr, maxy, maxx);
                int start_row;
                if (g_settings.no_meters) start_row=1;
                else {
                    // meters rows: 1 + cpu_rows + 3 +1 (blank) +1 (tabs) +1 (header) = ?
                    // Compute cpu rows as before
                    int cols = maxx/5; if (cols<1) cols=1; if (cols>g_ncpu) cols=g_ncpu;
                    int cpu_rows = (g_ncpu+cols-1)/cols;
                    if (g_ncpu<=8) cpu_rows=g_ncpu;
                    start_row = 1 + cpu_rows + 3 + 1 + 1 + 1; // blank top + cpu + mem/swp/uptime (3) + blank + tabs + header
                }
                draw_processes(stdscr, start_row, *selected);
                draw_search_footer(query);
            }
        } else if (ch == KEY_F(15)) { // Shift-F3 (often F15)
            if (qlen>0) {
                int prv = find_search_match(query, *selected-1, -1);
                if (prv>=0) *selected = prv;
                int maxy, maxx;
                getmaxyx(stdscr, maxy, maxx);
                int start_row;
                if (g_settings.no_meters) start_row=1;
                else {
                    int cols = maxx/5; if (cols<1) cols=1; if (cols>g_ncpu) cols=g_ncpu;
                    int cpu_rows = (g_ncpu+cols-1)/cols;
                    if (g_ncpu<=8) cpu_rows=g_ncpu;
                    start_row = 1 + cpu_rows + 3 + 1 + 1 + 1;
                }
                draw_processes(stdscr, start_row, *selected);
                draw_search_footer(query);
            }
        } else if (ch == KEY_BACKSPACE || ch == 127 || ch == 8) {
            if (qlen>0) {
                qlen--;
                query[qlen]='\0';
                draw_search_footer(query);
                // Update selection to first match from top? Or keep?
                if (qlen>0) {
                    int m = find_search_match(query, 0, 1);
                    if (m>=0) *selected=m;
                } else {
                    *selected=orig_selected;
                }
                // Redraw
                int maxy, maxx;
                getmaxyx(stdscr, maxy, maxx);
                int start_row;
                if (g_settings.no_meters) start_row=1;
                else {
                    int cols = maxx/5; if (cols<1) cols=1; if (cols>g_ncpu) cols=g_ncpu;
                    int cpu_rows = (g_ncpu+cols-1)/cols;
                    if (g_ncpu<=8) cpu_rows=g_ncpu;
                    start_row = 1 + cpu_rows + 3 + 1 + 1 + 1;
                }
                draw_processes(stdscr, start_row, *selected);
                draw_search_footer(query);
            }
        } else if (ch >= 32 && ch < 127) {
            if (qlen < (int)sizeof(query)-1) {
                query[qlen++]=ch;
                query[qlen]='\0';
                draw_search_footer(query);
                int m = find_search_match(query, 0, 1);
                if (m>=0) *selected=m;
                int maxy, maxx;
                getmaxyx(stdscr, maxy, maxx);
                int start_row;
                if (g_settings.no_meters) start_row=1;
                else {
                    int cols = maxx/5; if (cols<1) cols=1; if (cols>g_ncpu) cols=g_ncpu;
                    int cpu_rows = (g_ncpu+cols-1)/cols;
                    if (g_ncpu<=8) cpu_rows=g_ncpu;
                    start_row = 1 + cpu_rows + 3 + 1 + 1 + 1;
                }
                draw_processes(stdscr, start_row, *selected);
                draw_search_footer(query);
            }
        }
        // Ignore other keys
    }
    // Restore timeout will be done by caller
}

// For filter, need to rebuild display list as user types
extern void build_display_list(void);
void do_filter(int *selected) {
    char query[256] = "";
    int qlen=0;
    // If there's already a filter (from -F or previous interactive), show it? Original F4 shows current filter? When you press F4 with existing filter, it shows prompt with current filter? Or empty? Let's assume empty initially, but if g_settings.filter exists, preload it?
    // For simplicity, start empty. If user had -F filter, pressing F4 should show current filter? Let's preload.
    if (g_settings.filter) {
        strncpy(query, g_settings.filter, sizeof(query)-1);
        qlen=strlen(query);
    }
    char *saved_filter = g_settings.filter ? strdup(g_settings.filter) : NULL;
    static char filter_buf[256]; // to hold new filter (must persist after function, since g_settings.filter points to it)
    timeout(-1);
    draw_filter_footer(query);
    // Initially, display already filtered by saved_filter (if any). As user types, update.
    while (1) {
        int ch = getch();
        if (ch == 27) { // ESC: clear filter (show all)? Original EscClear clears? Actually footer says EscClear (clear filter, show all?) Or Esc cancels and reverts? For F4, Esc should clear filter (show all) and return? Let's implement: ESC clears to NULL (show all) and return? But if there was initial -F filter, should it revert to initial or clear to all? Original: "To cancel filtering, enter the Filter option again and press Esc." That suggests Esc clears filter (show all). Even if initial -F existed? Probably clears to all. Good. So ESC sets filter to NULL.
            if (saved_filter) free(saved_filter);
            g_settings.filter = NULL;
            build_display_list();
            *selected=0;
            break;
        } else if (ch == '\n' || ch == '\r' || ch == KEY_ENTER) {
            // Done: apply query (if empty, clear to NULL, else set)
            if (qlen==0) {
                if (saved_filter) free(saved_filter);
                g_settings.filter = NULL;
            } else {
                strncpy(filter_buf, query, sizeof(filter_buf)-1);
                if (saved_filter) free(saved_filter);
