                draw_processes(stdscr, start_row, *selected);
                draw_filter_footer(query);
            }
        } else if (ch >= 32 && ch < 127) {
            if (qlen < (int)sizeof(query)-1) {
                query[qlen++]=ch; query[qlen]='\0';
                draw_filter_footer(query);
                strncpy(filter_buf, query, sizeof(filter_buf)-1);
                g_settings.filter = filter_buf;
                build_display_list();
                *selected=0;
                int maxy, maxx;
                getmaxyx(stdscr, maxy, maxx);
                int start_row;
                if (g_settings.no_meters) start_row=1;
                else {
                    int cols = maxx/5; if (cols<1) cols=1; if (cols>g_ncpu) cols=g_ncpu;
                    int cpu_rows = (g_ncpu+cols-1)/cols;
                    if (g_ncpu<=8) cpu_rows=g_ncpu;
                    start_row = 1 + cpu_rows + 3 + 1 + 1 + 1;
